{
	"@context": "https://schema.org",
	"@type": "FAQPage",
	"mainEntity": [
		{
			"@type": "Question",
			"name": "What is a Hair Color Bar?",
			"acceptedAnswer": {
				"@type": "Answer",
				"text": "At Madison Reed Hair Color Bars, our Hair Color Experts color your hair for you for a fraction of the price - and in less time - than a typical salon. We use our premium, ammonia-free hair color and care products made with ingredients you can feel good about to give you your best hair color ever. Our services include All-Over Color, Roots, Highlights, Gloss, and more – and are delivered with love by our pro colorists. You can easily book an appointment online or through our app - and walk-ins are welcome. We have over 90 locations nationwide, and you can be confident knowing you will get the same gorgeous results no matter where you go!"
			}
		},
		{
			"@type": "Question",
			"name": "What can I expect at a Hair Color Bar?",
			"acceptedAnswer": {
				"@type": "Answer",
				"text": "Here’s what to expect at your first appointment: </br></br>\n\n<a href=\"/color-advisor\" class=\"bold underline\">Find your perfect match</a> with the help of a pro colorist and meet the team of stylists who will be taking care of you during your appointment. </br></br>\n\nSit back and relax as a pro colorist applies our premium hair color, crafted in Italy! </br></br>\n\nTime for shampoo! Upgrade your rinse with an in-bowl, deep-conditioning treatment for added moisture and shine.</br></br>\n\nFinish in style with a professional blowout, or self-dry for added convenience. We promise you will leave your appointment feeling confident and unstoppable.</br></br>\n\n<a href=\"/mobile-app\" class=\"bold underline\">Download our app</a> for a seamless check-in and check-out experience, plus stay updated on your progress throughout your appointment.</br></br>"
			}
		},
		{
			"@type": "Question",
			"name": "What services are offered?",
			"acceptedAnswer": {
				"@type": "Answer",
				"text": "We offer a variety of hair color services including Roots, All-Over Color, Highlights, Gloss, Blowouts, and more! You can also choose from permanent hair color for 100% gray coverage, or demi-permanent hair color that washes out gradually. We also offer customized memberships that fit your needs, schedule, and budget!"
			}
		},
		{
			"@type": "Question",
			"name": "How do I make an appointment?",
			"acceptedAnswer": {
				"@type": "Answer",
				"text": "You can easily book and manage your appointments online or on our app - and walk-ins are welcome! Many of our 90+ locations nationwide are open 7 days a week so you can get your best hair color ever - wherever and whenever you want it!"
			}
		}
	]
}

